import{_ as e,o as a,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Meditation and Concentration","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/meditation-and-concentration.md","filePath":"en/guide/magic/meditation-and-concentration.md"}'),r={name:"en/guide/magic/meditation-and-concentration.md"};function o(d,t,s,c,l,m){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="meditation-and-concentration" tabindex="-1">Meditation and Concentration <a class="header-anchor" href="#meditation-and-concentration" aria-label="Permalink to &quot;Meditation and Concentration&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Meditation concerns organization, preparation and resource recovery.</li><li>Concentration concerns stability under pressure; it is not automatically another skillcap cost.</li><li>Fizzle and interruption differ, and their exact costs remain unresolved.</li></ul><p><a href="/Syrolands-Public/en/game-design/magic.html#meditation-and-concentration">Full design specification</a></p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role / boundary</th></tr></thead><tbody><tr><td>Meditation</td><td>Meditation is proposed as mental organization as well as resource recovery: preparing difficult patterns, arranging Active Memory, recovering readiness and using learned mental states with trade-offs.</td></tr><tr><td>Concentration</td><td>Concentration concerns stability under pressure. Damage, movement, local trauma, repeated attacks, fatigue, difficult variants and certain effects may disrupt a cast. It is not automatically another skill that consumes the skillcap.</td></tr><tr><td>Fizzle and interruption</td><td>Fizzle means failing to execute a pattern correctly; interruption means pressure disrupts an attempt. Their costs and formulas remain undecided. More mana alone would not make an injured, pressured mage equivalent to an undisturbed one.</td></tr><tr><td>Open questions</td><td>No trance list or numeric bonus is finalized. <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Memory preparation</a> and <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">combat pressure</a> connect to this proposal without changing the current combat experiment.</td></tr></tbody></table><p><a href="/Syrolands-Public/en/game-design/magic.html">Related design specification</a></p>',8)])])}const g=e(r,[["render",o]]);export{p as __pageData,g as default};
